mapper.update:

UPDATE chat_rooms SET room_name = #{roomName}
WHERE chat_room_id = #{chatRoomId}
  AND workspace_member_id = #{myWorkId}
  AND chat = 'GROUP'

mapper.select:
SELECT status
FROM chat_room_members
WHERE chat_room_id = #{chatRoomId}
  AND workspace_member_id = #{workMemberId}

mapper.update:
UPDATE chat_room_members
SET status = 0, joined = SYSDATE, left = NULL,
    visible_after_message_id = #{visibleAfterMessageId},
    last_read_message_id = #{visibleAfterMessageId}

WHERE chat_room_id = #{chatRoomId}
  AND workspace_member_id = #{workMemberId}
  AND status = 1

UPDATE chat_room_members SET status = 1
WHERE chat_room_id = #{chatRoomId}
  AND workspace_member_id = #{workMemberId}
  AND status = 0

UPDATE chat_rooms cr SET workspace_member_id = #{targetWorkId}
WHERE cr.chat_room_id = #{chatRoomId}
  AND cr.chat = 'GROUP'
  AND cr.workspace_member_id = #{myWorkId}
  AND #{targetWorkId} != #{myWorkId}
  AND EXISTS (
      SELECT 1
      FROM chat_room_members crm

      JOIN workspace_members t_wm ON crm.workspace_member_id = t_wm.workspace_member_id

      JOIN workspace_members c_wm ON c_wm.workspace_member_id = cr.workspace_member_id

      WHERE crm.chat_room_id = cr.chat_room_id
        AND crm.workspace_member_id = #{targetWorkId}
        AND crm.status = 0
        AND t_wm.status = 0
        AND c_wm.status = 0

        AND t_wm.workspace_id = c_wm.workspace_id
  )

mapper.delete:
DELETE FROM chat_messages
WHERE chat_room_id = #{chatRoomId}
  AND EXISTS (
      SELECT 1 FROM chat_rooms
      WHERE chat_room_id = #{chatRoomId}
        AND chat = 'GROUP'
  )
  AND NOT EXISTS (
      SELECT 1 FROM chat_room_members
      WHERE chat_room_id = #{chatRoomId}
        AND status = 0
  )

DELETE FROM chat_room_members
WHERE chat_room_id = #{chatRoomId}
  AND EXISTS (
      SELECT 1 FROM chat_rooms
      WHERE chat_room_id = #{chatRoomId}
        AND chat = 'GROUP'
  )
  AND NOT EXISTS (
      SELECT 1 FROM chat_room_members
      WHERE chat_room_id = #{chatRoomId}
        AND status = 0
  )

DELETE FROM chat_rooms
WHERE chat_room_id = #{chatRoomId}
  AND chat = 'GROUP'
  AND NOT EXISTS (
      SELECT 1 FROM chat_room_members
      WHERE chat_room_id = #{chatRoomId}
  )
